function fixture(visualId, labels, values = [], stepLabels = undefined) {
  return {
    id: `fixture-${visualId.replace(/^visual-/, '')}`,
    visualId,
    labels,
    values,
    ...(stepLabels ? { stepLabels } : {}),
  };
}

