function inventory(
  visualId,
  assessedOutcomes,
  outcomeCriteria,
  cognitiveQuestion,
  storyboard,
) {
  return {
    visualId,
    assessedOutcomes,
    assessedCoverage: contextRagMemoryOutcomeRegistry.visuals[visualId],
    outcomeCriteria,
    cognitiveQuestion,
    storyboard,
  };
}

